WITH base AS (SELECT *, CONCAT(supplier_name, ' - ', city) AS supplier_name_city, UPPER(city) AS city_upper FROM suppliers WHERE city IS DISTINCT FROM 'Chiang Mai'), eligible AS (SELECT s.* FROM base s WHERE EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.product_name LIKE '%Backp%')), eligible_suppliers AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.stock_qty BETWEEN 106 AND 175)), scored AS (SELECT *, LEAD(rating) OVER w_running AS next_rating, LAG(rating) OVER w_running AS prev_rating, ROW_NUMBER() OVER w_running AS event_seq FROM eligible_suppliers WHERE rating IS NULL WINDOW w_running AS (PARTITION BY city ORDER BY rating, id)), deduped AS (SELECT * FROM scored QUALIFY ROW_NUMBER() OVER (PARTITION BY city, country ORDER BY next_rating DESC NULLS FIRST, id) = 1) SELECT id, supplier_name, country, rating, city_upper, event_seq FROM deduped
